///   suspend-inflated sample with no detected suspend).
///
/// Called at the end of [`print_report`] so the flag is the last
/// line of the bench's report, where it can't scroll out of mind.
fn warn_invalid(name: &str, hist: &Histogram<u64>, suspended_s: f64) {
