1	//! Generic bench driver: the [`Bench`] trait, adaptive outer/inner
2	//! loop sizing, and the band-histogram report.
3	
4	use std::hint::black_box;
5	
6	use hdrhistogram::Histogram;
7	
8	use crate::overhead::Overhead;
9	
10	const WARMUP: u64 = 10_000;
11	const ESTIMATE_STEPS: u64 = 1_000;
12	const ESTIMATE_SAMPLES: usize = 5;
13	const FRAMING_DOMINATION_RATIO: f64 = 10.0;
14	const MAX_INNER: u64 = 1_000;
15	
16	/// Histogram value bounds: 1 ns to 60 s at 3 sig figs. The high
17	/// bound is a sane-world ceiling for one recorded sample, not a
18	/// technical limit — [`record_sample`] clamps above it and
19	/// [`warn_invalid`] flags the run.
20	const HIST_LOW_NS: u64 = 1;
21	const HIST_HIGH_NS: u64 = 60_000_000_000;
22	
23	/// `CLOCK_BOOTTIME` minus `CLOCK_MONOTONIC` elapsed divergence
24	/// (seconds) at or above which [`warn_invalid`] reports that the
25	/// system suspended during the run.
26	const SUSPEND_WARN_S: f64 = 1.0;
27	
28	/// A benchmark workload: a named operation that `step()` performs
29	/// in a tight loop for sub-µs latency measurement. Implementors own
30	/// any setup state (channels, spawned threads, counters). `step()`
31	/// returns a value so the caller can `black_box` it against dead-code
32	/// elimination.
33	pub trait Bench {
34	    /// Human-readable name used in the report header.
35	    fn name(&self) -> &str;
36	
37	    /// Run one unit of work. Return any value derived from the work
38	    /// to defeat DCE — the caller black-boxes it.
39	    fn step(&mut self) -> u64;
40	}
41	
42	/// Runtime configuration for one [`run_adaptive`] call.
43	#[derive(Debug)]
44	pub struct RunCfg<'a> {
45	    /// Calibrated apparatus overhead (framing + loop/iter) used to
46	    /// compute the `adjusted` mean columns in the report.
47	    pub overhead: &'a Overhead,
48	    /// Wall-clock seconds budget for time-based runs. Ignored when
49	    /// `outer_override` is set.
50	    pub target_seconds: f64,
51	    /// Force a fixed outer-loop count, bypassing the time budget.
52	    pub outer_override: Option<u64>,
53	    /// Force a fixed inner-loop count, bypassing the
54	    /// overhead-dominated auto-sizing.
55	    pub inner_override: Option<u64>,
56	    /// Core pool for thread pinning. Indexed positionally with
57	    /// wrap-around via [`core_for`][RunCfg::core_for]; empty means
58	    /// no pinning.
59	    pub pin_cores: &'a [usize],
60	    /// When set, [`crate::tprobe::TProbe::report`] emits raw TSC
61	    /// ticks instead of nanoseconds. Plumbed from the `-t/--ticks`
62	    /// CLI flag.
63	    pub report_ticks: bool,
64	}
65	
66	impl RunCfg<'_> {
67	    /// CPU id for the bench's `thread_idx`-th thread, using
68	    /// wrap-around over the pool. Returns `None` when the pool is
69	    /// empty so callers can treat unpinned and pinned runs uniformly.
70	    pub fn core_for(&self, thread_idx: usize) -> Option<usize> {
71	        if self.pin_cores.is_empty() {
72	            None
73	        } else {
74	            Some(self.pin_cores[thread_idx % self.pin_cores.len()])
75	        }
76	    }
77	}
78	
79	/// Drive `bench` against `cfg` and return
80	/// `(histogram, outer, inner, duration_s, suspended_s)`.
81	///
82	/// After a fixed warmup, `inner` is auto-sized so apparatus framing
83	/// doesn't dominate (skipped when `cfg.inner_override` is set). The
84	/// outer loop runs either for `cfg.outer_override` iterations or
85	/// until `cfg.target_seconds` elapses. `suspended_s` is the time
86	/// the system spent suspended during the measured run (see
87	/// [`ClockPair`]); pass it to [`print_report`], which flags the
88	/// poisoned stats when it is non-trivial.
89	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64, f64) {
90	    for _ in 0..WARMUP {
91	        black_box(bench.step());
92	    }
93	
94	    let step_cost_ns = estimate_step_cost(bench);
95	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
96	    let inner = cfg
97	        .inner_override
98	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
99	
100	    let clocks = ClockPair::now();
101	    let (hist, outer, duration_s) = match cfg.outer_override {
102	        Some(outer) => {
103	            let (hist, duration_s) = run_counted(bench, outer, inner);
104	            (hist, outer, duration_s)
105	        }
106	        None => {
107	            let (hist, duration_s) = run_timed(bench, cfg.target_seconds, inner);
108	            let outer = hist.len();
109	            (hist, outer, duration_s)
110	        }
111	    };
112	    (hist, outer, inner, duration_s, clocks.suspended_s())
113	}
114	
115	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
116	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
117	        .map(|_| {
118	            let start = minstant::Instant::now();
119	            for _ in 0..ESTIMATE_STEPS {
120	                black_box(bench.step());
121	            }
122	            let total = start.elapsed().as_nanos() as u64;
123	            total as f64 / ESTIMATE_STEPS as f64
124	        })
125	        .collect();
126	    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
127	    samples[ESTIMATE_SAMPLES / 2]
128	}
129	
130	fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
131	    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
132	    target.clamp(1, MAX_INNER)
133	}
134	
135	fn run_counted<B: Bench>(bench: &mut B, outer: u64, inner: u64) -> (Histogram<u64>, f64) {
136	    let mut hist = new_hist();
137	    let run_start = minstant::Instant::now();
138	    for _ in 0..outer {
139	        record_sample(bench, inner, &mut hist);
140	    }
141	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
142	    (hist, duration_s)
143	}
144	
145	fn run_timed<B: Bench>(bench: &mut B, target_seconds: f64, inner: u64) -> (Histogram<u64>, f64) {
146	    let mut hist = new_hist();
147	    let target_ns = (target_seconds * 1e9) as u128;
148	    let run_start = minstant::Instant::now();
149	    loop {
150	        record_sample(bench, inner, &mut hist);
151	        if run_start.elapsed().as_nanos() >= target_ns {
152	            break;
153	        }
154	    }
155	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
156	    (hist, duration_s)
157	}
158	
159	/// Fresh histogram over `[HIST_LOW_NS, HIST_HIGH_NS]` at 3 sig
160	/// figs, resize disabled — out-of-range samples clamp (see
161	/// [`record_sample`]) rather than grow the histogram.
162	fn new_hist() -> Histogram<u64> {
163	    Histogram::<u64>::new_with_bounds(HIST_LOW_NS, HIST_HIGH_NS, 3).unwrap() // OK: constant bounds
164	}
165	
166	/// Time one sample (`inner` back-to-back calls), divide down to a
167	/// per-call value, and record it, clamping at the histogram
168	/// bounds — a suspend-inflated or wedged sample must not panic a
169	/// long run ([`warn_invalid`] flags it instead).
170	fn record_sample<B: Bench>(bench: &mut B, inner: u64, hist: &mut Histogram<u64>) {
171	    let start = minstant::Instant::now();
172	    for _ in 0..inner {
173	        black_box(bench.step());
174	    }
175	    let elapsed_ns = start.elapsed().as_nanos() as u64;
176	    hist.saturating_record(round_elapsed(elapsed_ns, inner));
177	}
178	
179	fn round_elapsed(elapsed_ns: u64, inner: u64) -> u64 {
180	    (elapsed_ns + inner / 2) / inner
181	}
182	
183	/// Paired run-start readings of `CLOCK_MONOTONIC` and
184	/// `CLOCK_BOOTTIME`, for detecting a system suspend that spanned
185	/// a measurement run.
186	///
187	/// - `CLOCK_MONOTONIC` freezes while the system is suspended;
188	///   `CLOCK_BOOTTIME` keeps counting — the divergence of the two
189	///   elapsed times is the time spent suspended.
190	/// - Uses std `Instant` (`CLOCK_MONOTONIC`), not `minstant`: we
191	///   think the TSC keeps counting across s2idle suspend, which is
192	///   exactly the clock behavior being detected.
193	struct ClockPair {
194	    mono: std::time::Instant,
195	    boot_ns: u64,
196	}
197	
198	impl ClockPair {
199	    /// Capture both clocks now.
200	    fn now() -> Self {
201	        Self {
202	            mono: std::time::Instant::now(),

