1	//! Generic bench driver: the [`Bench`] trait, adaptive outer/inner
2	//! loop sizing, and the band-histogram report.
3	
4	use std::hint::black_box;
5	
6	use hdrhistogram::Histogram;
7	
8	use crate::bands::{self, BandLabels};
9	use crate::overhead::Overhead;
10	
11	const WARMUP: u64 = 10_000;
12	const ESTIMATE_STEPS: u64 = 1_000;
13	const ESTIMATE_SAMPLES: usize = 5;
14	const FRAMING_DOMINATION_RATIO: f64 = 10.0;
15	const MAX_INNER: u64 = 1_000;
16	
17	/// Histogram value bounds: 1 ns to 60 s at 3 sig figs. The high
18	/// bound is a sane-world ceiling for one recorded sample, not a
19	/// technical limit — [`record_sample`] clamps above it and
20	/// [`warn_invalid`] flags the run.
21	const HIST_LOW_NS: u64 = 1;
22	const HIST_HIGH_NS: u64 = 60_000_000_000;
23	
24	/// `CLOCK_BOOTTIME` minus `CLOCK_MONOTONIC` elapsed divergence
25	/// (seconds) at or above which [`warn_invalid`] reports that the
26	/// system suspended during the run.
27	const SUSPEND_WARN_S: f64 = 1.0;
28	
29	/// A benchmark workload: a named operation that `step()` performs
30	/// in a tight loop for sub-µs latency measurement. Implementors own
31	/// any setup state (channels, spawned threads, counters). `step()`
32	/// returns a value so the caller can `black_box` it against dead-code
33	/// elimination.
34	pub trait Bench {
35	    /// Human-readable name used in the report header.
36	    fn name(&self) -> &str;
37	
38	    /// Run one unit of work. Return any value derived from the work
39	    /// to defeat DCE — the caller black-boxes it.
40	    fn step(&mut self) -> u64;
41	}
42	
43	/// Runtime configuration for one [`run_adaptive`] call.
44	#[derive(Debug)]
45	pub struct RunCfg<'a> {
46	    /// Calibrated apparatus overhead (framing + loop/iter) used to
47	    /// compute the `adjusted` mean columns in the report.
48	    pub overhead: &'a Overhead,
49	    /// Wall-clock seconds budget for time-based runs. Ignored when
50	    /// `outer_override` is set.
51	    pub target_seconds: f64,
52	    /// Force a fixed outer-loop count, bypassing the time budget.
53	    pub outer_override: Option<u64>,
54	    /// Force a fixed inner-loop count, bypassing the
55	    /// overhead-dominated auto-sizing.
56	    pub inner_override: Option<u64>,
57	    /// Core pool for thread pinning. Indexed positionally with
58	    /// wrap-around via [`core_for`][RunCfg::core_for]; empty means
59	    /// no pinning.
60	    pub pin_cores: &'a [usize],
61	    /// When set, [`crate::tprobe::TProbe::report`] emits raw TSC
62	    /// ticks instead of nanoseconds. Plumbed from the `-t/--ticks`
63	    /// CLI flag.
64	    pub report_ticks: bool,
65	    /// Band-label style for [`print_report`] histogram rows.
66	    /// Plumbed from the `--band-labels` CLI flag.
67	    pub band_labels: BandLabels,
68	}
69	
70	impl RunCfg<'_> {
71	    /// CPU id for the bench's `thread_idx`-th thread, using
72	    /// wrap-around over the pool. Returns `None` when the pool is
73	    /// empty so callers can treat unpinned and pinned runs uniformly.
