12	const ESTIMATE_STEPS: u64 = 1_000;
13	const ESTIMATE_SAMPLES: usize = 5;
14	const FRAMING_DOMINATION_RATIO: f64 = 10.0;
15	const MAX_INNER: u64 = 1_000;
16	
17	/// Histogram value bounds: 1 ps to 60 s at 3 sig figs. Values
18	/// are recorded in **picoseconds** — the timer reads integer ns,
19	/// but dividing a sample by `inner` in ps keeps the true sub-ns
20	/// per-call precision that ns recording truncated (a 4.7 ns call
21	/// no longer rounds to 5). The high bound is a sane-world
22	/// ceiling for one recorded sample, not a technical limit —
23	/// [`record_sample`] clamps above it and [`warn_invalid`] flags
24	/// the run.
25	const HIST_LOW_PS: u64 = 1;
26	const HIST_HIGH_PS: u64 = 60_000_000_000_000;
27	
28	/// Picoseconds per nanosecond: recorded values are ps, display
29	/// is ns.
30	const PS_PER_NS: f64 = 1000.0;
31	
32	/// Decimal digits on the report's time columns. One digit shows
33	/// the sub-ns precision ps recording captures; becomes
34	/// flag-controlled when `--decimals` lands.
35	const TIME_DECIMALS: usize = 1;
36	
37	/// `CLOCK_BOOTTIME` minus `CLOCK_MONOTONIC` elapsed divergence
38	/// (seconds) at or above which [`warn_invalid`] reports that the
39	/// system suspended during the run.
40	const SUSPEND_WARN_S: f64 = 1.0;
41	
42	/// A benchmark workload: a named operation that `step()` performs
43	/// in a tight loop for sub-µs latency measurement. Implementors own
44	/// any setup state (channels, spawned threads, counters). `step()`
45	/// returns a value so the caller can `black_box` it against dead-code
46	/// elimination.
47	pub trait Bench {
48	    /// Human-readable name used in the report header.
49	    fn name(&self) -> &str;
50	
51	    /// Run one unit of work. Return any value derived from the work
52	    /// to defeat DCE — the caller black-boxes it.
53	    fn step(&mut self) -> u64;
54	}
55	
56	/// Runtime configuration for one [`run_adaptive`] call.
57	#[derive(Debug)]
58	pub struct RunCfg<'a> {
59	    /// Calibrated apparatus overhead (framing + loop/iter) used to
60	    /// compute the `adjusted` mean columns in the report.
61	    pub overhead: &'a Overhead,
62	    /// Wall-clock seconds budget for time-based runs. Ignored when
63	    /// `outer_override` is set.
64	    pub target_seconds: f64,
65	    /// Force a fixed outer-loop count, bypassing the time budget.
66	    pub outer_override: Option<u64>,
67	    /// Force a fixed inner-loop count, bypassing the
68	    /// overhead-dominated auto-sizing.
69	    pub inner_override: Option<u64>,
70	    /// Core pool for thread pinning. Indexed positionally with
71	    /// wrap-around via [`core_for`][RunCfg::core_for]; empty means
72	    /// no pinning.
73	    pub pin_cores: &'a [usize],
74	    /// When set, [`crate::tprobe::TProbe::report`] emits raw TSC
75	    /// ticks instead of nanoseconds. Plumbed from the `-t/--ticks`
76	    /// CLI flag.
77	    pub report_ticks: bool,
78	    /// Band-label style for [`print_report`] histogram rows.
79	    /// Plumbed from the `--band-labels` CLI flag.
80	    pub band_labels: BandLabels,
81	}
82	
83	impl RunCfg<'_> {
84	    /// CPU id for the bench's `thread_idx`-th thread, using
85	    /// wrap-around over the pool. Returns `None` when the pool is
86	    /// empty so callers can treat unpinned and pinned runs uniformly.
87	    pub fn core_for(&self, thread_idx: usize) -> Option<usize> {
88	        if self.pin_cores.is_empty() {
89	            None
90	        } else {
91	            Some(self.pin_cores[thread_idx % self.pin_cores.len()])
92	        }
93	    }
94	}
95	
96	/// Drive `bench` against `cfg` and return
97	/// `(histogram, outer, inner, duration_s, suspended_s)`.
98	///
99	/// After a fixed warmup, `inner` is auto-sized so apparatus framing
100	/// doesn't dominate (skipped when `cfg.inner_override` is set). The
101	/// outer loop runs either for `cfg.outer_override` iterations or
102	/// until `cfg.target_seconds` elapses. `suspended_s` is the time
103	/// the system spent suspended during the measured run (see
104	/// [`ClockPair`]); pass it to [`print_report`], which flags the
105	/// poisoned stats when it is non-trivial.
106	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64, f64) {
107	    for _ in 0..WARMUP {
108	        black_box(bench.step());
109	    }
110	
111	    let step_cost_ns = estimate_step_cost(bench);
112	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
113	    let inner = cfg
114	        .inner_override
115	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
116	
117	    let clocks = ClockPair::now();
118	    let (hist, outer, duration_s) = match cfg.outer_override {
119	        Some(outer) => {
120	            let (hist, duration_s) = run_counted(bench, outer, inner);
121	            (hist, outer, duration_s)
122	        }
123	        None => {
124	            let (hist, duration_s) = run_timed(bench, cfg.target_seconds, inner);
125	            let outer = hist.len();
126	            (hist, outer, duration_s)
127	        }
128	    };
129	    (hist, outer, inner, duration_s, clocks.suspended_s())
130	}
131	
132	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
133	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
134	        .map(|_| {
135	            let start = minstant::Instant::now();
136	            for _ in 0..ESTIMATE_STEPS {
137	                black_box(bench.step());
138	            }
139	            let total = start.elapsed().as_nanos() as u64;
140	            total as f64 / ESTIMATE_STEPS as f64
141	        })
142	        .collect();
143	    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
144	    samples[ESTIMATE_SAMPLES / 2]
145	}
146	
147	fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
148	    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
149	    target.clamp(1, MAX_INNER)
150	}
151	
152	fn run_counted<B: Bench>(bench: &mut B, outer: u64, inner: u64) -> (Histogram<u64>, f64) {
153	    let mut hist = new_hist();
154	    let run_start = minstant::Instant::now();
155	    for _ in 0..outer {
