162	fn run_timed<B: Bench>(bench: &mut B, target_seconds: f64, inner: u64) -> (Histogram<u64>, f64) {
163	    let mut hist = new_hist();
164	    let target_ns = (target_seconds * 1e9) as u128;
165	    let run_start = minstant::Instant::now();
