/// the built-in-default [`Config`] when no file exists; errors on a
/// present-but-unreadable or malformed file.
///
/// Layering: start from the XDG file, then overlay the local file
/// (scalars replace, profiles merge by key), so the nearer file
/// wins per field.
pub fn load() -> Result<Config, String> {
    let mut raw = RawConfig::default();
    if let Some(path) = xdg_path() {
        overlay(&mut raw, &path)?;
    }
    overlay(&mut raw, &PathBuf::from(LOCAL_FILE))?;
    validate(raw)
}

