1	//! Layered configuration for defaults: built-in < XDG config file <
2	//! project-local file < CLI flags.
3	//!
4	//! - **XDG file** — `$XDG_CONFIG_HOME/iiac-perf/config.toml`, or
5	//!   `$HOME/.config/iiac-perf/config.toml` when `XDG_CONFIG_HOME`
6	//!   is unset. The per-user home for defaults and pin profiles.
7	//! - **Project-local file** — [`LOCAL_FILE`] in the current
8	//!   directory (no upward walk). Overrides the XDG file
9	//!   field-by-field; profiles merge by key.
10	//! - **CLI** — always wins, resolved in `main` after [`load`].
11	//!
12	//! A malformed or unreadable-but-present file is a hard error, so a
13	//! typo surfaces rather than silently reverting to built-ins.
14	
15	use std::collections::BTreeMap;
16	use std::path::PathBuf;
17	
18	use serde::Deserialize;
19	
20	use crate::bands::BandLabels;
21	
22	/// Project-local override filename, looked up in the current
23	/// directory only.
24	const LOCAL_FILE: &str = "iiac-perf.toml";
25	
26	/// Inclusive upper bound on `decimals`, mirroring the
27	/// `--decimals` CLI `value_parser` range.
28	const DECIMALS_MAX: u8 = 3;
29	
30	/// The on-disk TOML shape, before validation. Scalars are
31	/// `Option` so an absent key stays absent (letting a lower layer
32	/// or built-in default show through); unknown keys are rejected
33	/// to catch typos.
34	#[derive(Debug, Default, Deserialize)]
35	#[serde(deny_unknown_fields)]
36	struct RawConfig {
37	    /// Default `--duration` seconds.
38	    duration: Option<f64>,
39	    /// Default `--band-labels` style, as its lowercase name.
40	    band_labels: Option<String>,
41	    /// Default `--decimals` count.
42	    decimals: Option<u8>,
43	    /// Named pin profiles: name -> `--pin` core spec.
44	    #[serde(default)]
45	    profiles: BTreeMap<String, String>,
46	}
47	
48	/// The merged, validated configuration handed to `main`.
49	///
50	/// Each scalar is `Option`: `None` means "no config opinion, use
51	/// the built-in default". Profiles are a flat name->spec map.
52	#[derive(Debug, Default, PartialEq)]
53	pub struct Config {
54	    /// Default `--duration` seconds, if configured.
55	    pub duration: Option<f64>,
56	    /// Default `--band-labels` style, if configured.
57	    pub band_labels: Option<BandLabels>,
58	    /// Default `--decimals` count, if configured.
59	    pub decimals: Option<u8>,
60	    /// Named pin profiles: name -> `--pin` core spec.
61	    pub profiles: BTreeMap<String, String>,
62	}
63	
64	impl Config {
65	    /// Resolve a `--pin` spec against the configured profiles: a
66	    /// spec that names a profile expands to that profile's core
67	    /// spec; anything else is returned unchanged for
68	    /// [`crate::pin::parse_cores`] to parse as a raw core list.
69	    pub fn resolve_pin<'a>(&'a self, spec: &'a str) -> &'a str {
70	        self.profiles.get(spec).map(String::as_str).unwrap_or(spec)
71	    }
72	}
73	
74	/// The XDG config-file path: `$XDG_CONFIG_HOME/iiac-perf/config.toml`,
75	/// falling back to `$HOME/.config/...`. `None` if neither env var is
76	/// set (e.g. a stripped-down service environment).
77	fn xdg_path() -> Option<PathBuf> {
78	    let base = match std::env::var_os("XDG_CONFIG_HOME") {
79	        Some(x) if !x.is_empty() => PathBuf::from(x),
80	        _ => PathBuf::from(std::env::var_os("HOME")?).join(".config"),
81	    };
82	    Some(base.join("iiac-perf").join("config.toml"))
83	}
84	
85	/// Load and merge the XDG and project-local config files. Returns
86	/// the merged [`Config`] plus the paths of the files that actually
87	/// existed (for the startup banner). Built-in-default `Config` when
88	/// no file exists; errors on a present-but-unreadable or malformed
89	/// file.
90	///
91	/// Layering: start from the XDG file, then overlay the local file
92	/// (scalars replace, profiles merge by key), so the nearer file
93	/// wins per field.
94	pub fn load() -> Result<(Config, Vec<PathBuf>), String> {
95	    let mut raw = RawConfig::default();
96	    let mut loaded = Vec::new();
97	    if let Some(path) = xdg_path()
98	        && overlay(&mut raw, &path)?
99	    {
100	        loaded.push(path);
101	    }
102	    let local = PathBuf::from(LOCAL_FILE);
103	    if overlay(&mut raw, &local)? {
104	        loaded.push(local);
105	    }
106	    Ok((validate(raw)?, loaded))
107	}
108	
109	/// Read one config file and overlay it onto `base`: each present
110	/// scalar replaces `base`'s, and profiles are merged by key (the
111	/// file's entries win). Returns whether the file existed; a missing
112	/// file is a no-op returning `false`.
113	fn overlay(base: &mut RawConfig, path: &PathBuf) -> Result<bool, String> {
114	    let text = match std::fs::read_to_string(path) {
115	        Ok(t) => t,
116	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(false),
117	        Err(e) => return Err(format!("reading {}: {e}", path.display())),
118	    };
119	    let over: RawConfig =
120	        toml::from_str(&text).map_err(|e| format!("parsing {}: {e}", path.display()))?;
121	    if over.duration.is_some() {
122	        base.duration = over.duration;
123	    }
124	    if over.band_labels.is_some() {
125	        base.band_labels = over.band_labels;
126	    }
127	    if over.decimals.is_some() {
128	        base.decimals = over.decimals;
129	    }
130	    base.profiles.extend(over.profiles);
131	    Ok(true)
132	}
133	
134	/// Validate a merged [`RawConfig`] into a [`Config`]: map the
135	/// `band_labels` name to the enum and range-check `decimals`.
136	fn validate(raw: RawConfig) -> Result<Config, String> {
137	    let band_labels = match raw.band_labels {
138	        None => None,
139	        Some(s) => Some(match s.as_str() {
140	            "zpn" => BandLabels::Zpn,
141	            "frac" => BandLabels::Frac,
142	            "both" => BandLabels::Both,
143	            other => {
144	                return Err(format!(
145	                    "band_labels: {other:?} is not one of zpn, frac, both"
146	                ));
147	            }
148	        }),
149	    };
150	    if let Some(d) = raw.decimals
151	        && d > DECIMALS_MAX
152	    {
153	        return Err(format!(
154	            "decimals: {d} exceeds the maximum of {DECIMALS_MAX}"
155	        ));
156	    }
157	    Ok(Config {
158	        duration: raw.duration,
159	        band_labels,
160	        decimals: raw.decimals,
161	        profiles: raw.profiles,
162	    })
163	}
164	
165	#[cfg(test)]
166	mod tests {
167	    use super::*;
168	
169	    fn parse(text: &str) -> Result<Config, String> {
170	        validate(toml::from_str(text).map_err(|e| e.to_string())?)
171	    }
